//! `PROOF.md`: the human view of `proof/`, regenerated on every change and never read back.

use super::model::Verdict;
use super::store::Listing;

pub fn render_proof_md(
    repo: &str,
    branch: &str,
    listing: &Listing,
    verdicts: &[Verdict],
) -> String {
    let mut out = format!(
        "<!-- generated by bn from proof/ — do not edit; `bn proof show` has readiness -->\n\
         # Proof — {repo} / {branch}\n"
    );
    if listing.proofs.is_empty() {
        out.push_str("\nNo proof yet. `bn verify --for w1` or `bn proof add` records some.\n");
    }
    for p in &listing.proofs {
        let exit = p.exit.map(|c| format!(" · exit {c}")).unwrap_or_default();
        let sha = p
            .sha
            .as_deref()
            .map(|s| format!(" · {}", &s[..s.len().min(12)]))
            .unwrap_or_default();
        out.push_str(&format!(
            "\n## {} · {} · {}\n{} for {} · by {}{sha}{exit}\n",
            p.id,
            p.kind,
            p.title,
            p.created,
            if p.for_.is_empty() {
                "(no criteria yet)".to_string()
            } else {
                p.for_.join(", ")
            },
            p.author
        ));
        if let Some(a) = &p.attachment {
            out.push_str(&format!("[{a}](proof/{a})\n"));
        }
        for v in verdicts.iter().filter(|v| v.proof == p.id) {
            out.push_str(&format!(
                "- {} by {} ({}): {}\n",
                v.verdict.as_str(),
                v.judge,
                v.ts,
                v.reason
            ));
        }
    }
    if !listing.unregistered.is_empty() {
        out.push_str("\n## Unregistered\nFiles in proof/ nobody registered; they never count:\n");
        for f in &listing.unregistered {
            out.push_str(&format!("- {f}\n"));
        }
    }
    out
}
